import{_ as t,o as a,c as n,a3 as r}from"./chunks/framework.CpLciM8b.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Flakemetry","text":"Test intelligence, OpenTelemetry-native","tagline":"Treat every test run as a trace, not a report. Explainable flaky detection and AI root-cause across every run, branch, and refactor.","actions":[{"theme":"brand","text":"Get started","link":"/guide/introduction"},{"theme":"alt","text":"Self-host","link":"/guide/self-hosting"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/AKogut/flakemetry"}]},"features":[{"title":"Test observability","details":"Every run ingested as OTLP — full history per test, not per report. Historical analytics fall out of the telemetry instead of being bolted on."},{"title":"Stable test identity","details":"A multi-level fingerprint that survives file moves, renames, and parameterization, so a flaky test does not reset to zero when a file moves."},{"title":"Explainable flaky scoring","details":"A transparent Beta-Binomial score with human-readable reason codes — same commit different result, pass-on-rerun, and more. Not a black box."},{"title":"AI root-cause","details":"Failures are normalized and clustered cheaply; only genuinely new signatures reach an LLM, budget-gated and cached per cluster."},{"title":"CI-native, never blocks","details":"The write path returns 202 instantly and does the heavy work asynchronously. A GitHub Action and sticky PR comment ship out of the box."},{"title":"Works with any runner","details":"Native reporters for Playwright, Vitest, and Jest — plus JUnit XML ingestion for pytest, Go, Ruby, PHPUnit, and anything else."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1785494959000}'),s={name:"index.md"};function i(o,e,l,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h2 id="why-flakemetry" tabindex="-1">Why Flakemetry <a class="header-anchor" href="#why-flakemetry" aria-label="Permalink to &quot;Why Flakemetry&quot;">​</a></h2><p>Test reporters answer <em>&quot;what happened in this run?&quot;</em> Flakemetry answers <strong><em>&quot;is this test trustworthy, why is it failing, and is it getting worse?&quot;</em></strong> — across every run, branch, and refactor.</p><p>If every test execution is modelled as an <strong>OpenTelemetry span</strong>, then historical analytics, flaky scoring, and AI root-cause become natural extensions of the telemetry instead of bolted-on hacks. That single decision is the platform&#39;s technical moat.</p><p>Ready to try it? <a href="/flakemetry/v/2026-09-30/guide/self-hosting">Self-host in one command</a>, then <a href="/flakemetry/v/2026-09-30/guide/reporters">send your first run</a>.</p>',4)])])}const y=t(s,[["render",i]]);export{m as __pageData,y as default};
